import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class SecureFileAccess {
    public static void main(String[] args) {
        String userInput = request.getParameter("filename");

        // Define the base directory securely
        Path baseDir = Paths.get("/var/www/uploads").toAbsolutePath().normalize();

        // Construct the target path and normalize it to resolve any ".." sequences
        Path targetPath = baseDir.resolve(userInput).normalize();

        // Ensure the resolved path is still within the allowed base directory
        if (!targetPath.startsWith(baseDir)) {
            throw new SecurityException("Access denied: Invalid file path detected.");
        }

        try {
            // Safe to read the file now as we have validated the path
            byte[] data = java.nio.file.Files.readAllBytes(targetPath);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
